/**
 * Petshop Invoice Completed Attach Fix v3 (LIVE, GLOBAL scope)
 * Kritinis: snippet turi buti GLOBAL, nes completed laiskas siunciamas admin/REST kontekste, ne front-end.
 * Regeneruoja svieziа PVM saskaita faktura completed laisko siuntimo metu + nukerpa senus/WCDN priedus.
 */
if ( ! defined( 'ABSPATH' ) ) { return; }
add_filter( 'woocommerce_email_attachments', function ( $attachments, $email_id, $order, $email ) {
	if ( $email_id !== 'customer_completed_order' || ! ( $order instanceof WC_Order ) ) { return $attachments; }
	if ( ! function_exists( 'petshop_generate_invoice_pdf' ) ) { return $attachments; }
	$fresh_order = wc_get_order( $order->get_id() );
	if ( ! $fresh_order ) { return $attachments; }
	if ( function_exists( 'petshop_get_invoice_document_type' ) ) {
		$dt = petshop_get_invoice_document_type( $fresh_order );
		if ( $fresh_order->get_meta( '_petshop_invoice_document_type' ) !== $dt ) {
			$fresh_order->update_meta_data( '_petshop_invoice_document_type', $dt );
			$fresh_order->save();
		}
	}
	$fresh_pdf = petshop_generate_invoice_pdf( $order->get_id() );
	$clean = array();
	foreach ( (array) $attachments as $a ) {
		$b = basename( (string) $a );
		if ( stripos( $b, 'Isankstine-saskaita' ) !== false ) { continue; }
		if ( stripos( $b, 'PVM-saskaita' ) !== false ) { continue; }
		if ( stripos( $b, 'Invoice -' ) !== false ) { continue; }
		if ( preg_match( '/^invoice-\d+-\d+\.pdf$/i', $b ) ) { continue; }
		$clean[] = $a;
	}
	if ( $fresh_pdf && file_exists( $fresh_pdf ) ) {
		$clean[] = $fresh_pdf;
		$fresh_order->update_meta_data( '_petshop_completed_pdf', $fresh_pdf );
		$fresh_order->save();
	}
	$clean = array_values( $clean );
	update_option( 'ps_last_completed_attach', array(
		'time'  => time(),
		'order' => $order->get_id(),
		'ctx'   => is_admin() ? 'admin' : ( ( defined('REST_REQUEST') && REST_REQUEST ) ? 'rest' : 'front' ),
		'atts'  => array_map( 'basename', $clean ),
	), false );
	return $clean;
}, 50, 4 );

